#!/usr/bin/env node
// Copies contract ABIs from ../out and deployment addresses from ../deployments into src/generated/
// as typed TypeScript. Run with `npm run sync` after `forge build` and/or a deployment.
//
// ABIs are only rewritten when the Foundry artifacts exist, so the checked-in copies survive on a
// machine without Foundry. Addresses are always rewritten from whatever deployments/*.json exist.
//
// `npm run sync -- --check` writes nothing and exits 1 if the generated files are out of date.
// `npm run sync -- --local` also writes the local anvil chain's addresses (deployments/31337.json) to
// src/generated/addresses.local.ts. Without it that chain is left out, so a checked-in addresses.ts
// never carries a local deployment into a production build.
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const appDir = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const repoDir = resolve(appDir, "..");
const outDir = join(repoDir, "out");
const deploymentsDir = join(repoDir, "deployments");
const generatedDir = join(appDir, "src", "generated");

// Export name -> Foundry artifact name. ERC721 is OpenZeppelin's, used for approvals and its errors.
// MockRandomness is the local-chain randomness provider (test/mocks), used only on chain 31337.
const CONTRACTS = {
  marketplaceAbi: "Marketplace",
  treasuryAbi: "Treasury",
  buybackEngineAbi: "BuybackEngine",
  vaultAbi: "Vault",
  predictionMarketAbi: "PredictionMarket",
  pointsAbi: "Points",
  vaultRaffleAbi: "VaultRaffle",
  gamesAbi: "Games",
  ticketRaffleAbi: "TicketRaffle",
  lotteryAbi: "Lottery",
  ipLicenseManagerAbi: "IPLicenseManager",
  salesFloorOracleAbi: "SalesFloorOracle",
  pushFloorOracleAbi: "PushFloorOracle",
  erc721Abi: "ERC721",
  mockRandomnessAbi: "MockRandomness",
};

// Keys written by script/Deploy.s.sol. `demoCollection` is optional (script/SeedLocal.s.sol).
const REQUIRED_KEYS = [
  "treasury",
  "marketplace",
  "buybackEngine",
  "vault",
  "predictionMarket",
  "points",
  "vaultRaffle",
  "games",
  "ticketRaffle",
  "lottery",
  "ipLicenseManager",
  "salesFloorOracle",
  "pushFloorOracle",
  "randomness",
  "gamesRandomness",
  "vaultRandomness",
  "ticketRaffleRandomness",
  "lotteryRandomness",
  "owner",
];
const OPTIONAL_KEYS = ["demoCollection"];
const ADDRESS_RE = /^0x[0-9a-fA-F]{40}$/;

const HEADER = "// GENERATED by scripts/sync-contracts.mjs (npm run sync). Do not edit by hand.\n";

const check = process.argv.includes("--check");
let stale = false;

mkdirSync(generatedDir, { recursive: true });

/** Write `source` to src/generated/<name>, or in --check mode only compare it. */
function emit(name, source) {
  const path = join(generatedDir, name);
  if (!check) return writeFileSync(path, source);
  if (!existsSync(path) || readFileSync(path, "utf8") !== source) {
    stale = true;
    console.error(`src/generated/${name} is out of date. Run \`npm run sync\`.`);
  }
}

function errorSignature(item) {
  const type = (input) =>
    input.type.startsWith("tuple")
      ? `(${input.components.map(type).join(",")})${input.type.slice(5)}`
      : input.type;
  return `${item.name}(${item.inputs.map(type).join(",")})`;
}

function syncAbis() {
  const missing = Object.values(CONTRACTS).filter(
    (name) => !existsSync(join(outDir, `${name}.sol`, `${name}.json`)),
  );
  if (missing.length > 0) {
    console.warn(
      `ABIs: skipped, no Foundry artifact for ${missing.join(", ")} in ${outDir}. ` +
        "Run `forge build` in the repo root first. Keeping the existing src/generated/abis.ts.",
    );
    return false;
  }

  let source = HEADER + "\n";
  const errors = new Map();
  for (const [exportName, name] of Object.entries(CONTRACTS)) {
    const artifact = JSON.parse(readFileSync(join(outDir, `${name}.sol`, `${name}.json`), "utf8"));
    if (!Array.isArray(artifact.abi)) throw new Error(`${name}: artifact has no abi`);
    source += `export const ${exportName} = ${JSON.stringify(artifact.abi, null, 2)} as const;\n\n`;
    for (const item of artifact.abi) {
      if (item.type === "error") errors.set(errorSignature(item), item);
    }
  }
  const merged = [...errors.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([, item]) => item);
  source +=
    "/** Every custom error of every contract, deduplicated by signature. Appended to the ABI of a\n" +
    " *  call so that errors bubbling up from a nested contract can still be decoded by name. */\n" +
    `export const errorsAbi = ${JSON.stringify(merged, null, 2)} as const;\n`;
  emit("abis.ts", source);
  console.log(`ABIs: ${Object.keys(CONTRACTS).length} contracts, ${merged.length} distinct errors.`);
  return true;
}

/** The local anvil chain. Its addresses never go into the checked-in addresses.ts. */
const LOCAL_CHAIN_ID = 31337;
const local = process.argv.includes("--local");

function readDeployments() {
  const files = existsSync(deploymentsDir)
    ? readdirSync(deploymentsDir).filter((f) => /^\d+\.json$/.test(f))
    : [];
  const deployments = {};
  for (const file of files.sort((a, b) => parseInt(a) - parseInt(b))) {
    const chainId = parseInt(file);
    const json = JSON.parse(readFileSync(join(deploymentsDir, file), "utf8"));
    const entry = {};
    for (const key of REQUIRED_KEYS) {
      if (!ADDRESS_RE.test(json[key] ?? "")) {
        throw new Error(`deployments/${file}: missing or invalid address for "${key}"`);
      }
      entry[key] = json[key];
    }
    for (const key of OPTIONAL_KEYS) {
      if (json[key] === undefined) continue;
      if (!ADDRESS_RE.test(json[key])) throw new Error(`deployments/${file}: invalid "${key}"`);
      entry[key] = json[key];
    }
    deployments[chainId] = entry;
  }
  return deployments;
}

function syncAddresses() {
  const all = readDeployments();
  const { [LOCAL_CHAIN_ID]: localEntry, ...publicChains } = all;

  const fields = [
    ...REQUIRED_KEYS.map((k) => `  ${k}: Address;`),
    ...OPTIONAL_KEYS.map((k) => `  ${k}?: Address;`),
  ].join("\n");
  const source =
    HEADER +
    "\n" +
    "export type Address = `0x${string}`;\n\n" +
    `export type Deployment = {\n${fields}\n};\n\n` +
    "/** Keyed by chain id. A chain without an entry has no known deployment. The local anvil chain\n" +
    " *  (31337) is never listed here: see addresses.local.ts and src/local.ts. */\n" +
    `export const deployments: Partial<Record<number, Deployment>> = ${JSON.stringify(publicChains, null, 2)};\n`;
  emit("addresses.ts", source);
  const ids = Object.keys(publicChains);
  console.log(`Addresses: ${ids.length} public chain(s)${ids.length ? `: ${ids.join(", ")}` : ""}.`);

  // `npm run sync -- --local`: the local chain's addresses, in a git-ignored file that only a
  // development build (or one built with VITE_ENABLE_LOCAL=1) imports.
  if (!local) {
    if (localEntry) console.log("Addresses: deployments/31337.json was left out. Use `npm run sync -- --local` for a local chain.");
    return;
  }
  const localSource =
    HEADER +
    "// LOCAL DEVELOPMENT ONLY (npm run sync -- --local). Git-ignored; not part of a production build.\n\n" +
    'import type { Deployment } from "./addresses";\n\n' +
    `export const localDeployment: Deployment | undefined = ${localEntry ? JSON.stringify(localEntry, null, 2) : "undefined"};\n`;
  emit("addresses.local.ts", localSource);
  console.log(`Addresses: local chain ${LOCAL_CHAIN_ID} ${localEntry ? "written to" : "absent; emptied"} src/generated/addresses.local.ts.`);
}

syncAbis();
syncAddresses();
if (stale) process.exit(1);
